package com.bank.audit.service;

import java.util.logging.Logger;

// Finds the first and last index of an amount in a sorted array.
public class AuditRangeService {
    private static final Logger log = Logger.getLogger(AuditRangeService.class.getName());

    public int[] range(int[] amounts, int key) {
        int first = search(amounts, key, true);
        if (first == -1) {
            log.warning(() -> "Amount " + key + " not present");
            return new int[]{-1, -1};
        }
        int last = search(amounts, key, false);
        log.info(() -> "Amount " + key + " spans indices " + first + " to " + last);
        return new int[]{first, last};
    }

    private int search(int[] arr, int key, boolean findFirst) {
        int start = 0, end = arr.length - 1, result = -1;
        while (start <= end) {
            int mid = start + (end - start) / 2;
            if (key < arr[mid]) end = mid - 1;
            else if (key > arr[mid]) start = mid + 1;
            else {
                result = mid;                 // record candidate
                if (findFirst) end = mid - 1;  // bias left
                else start = mid + 1;          // bias right
            }
        }
        return result;
    }
}
