package com.bank.audit;

import com.bank.audit.service.AuditRangeService;
import java.util.Arrays;
import java.util.logging.Logger;

public class AuditRangeApplication {
    private static final Logger log = Logger.getLogger(AuditRangeApplication.class.getName());

    public static void main(String[] args) {
        AuditRangeService service = new AuditRangeService();
        int[] amounts = {1000, 3000, 3000, 3000, 5000};
        log.info("Range of 3000: " + Arrays.toString(service.range(amounts, 3000)));
